leverFrames[0].title=P('실험 1 · 왼쪽 1칸에 추 몇 개? 오른쪽은 2칸 1개','Trial 1: find the left count at position 1; right is 2×1');
leverFrames[0].startInputs={...leverFrames[0].inputs,leftCount:1};leverFrames[0].variable=['leftCount'];
leverFrames[1].title=P('실험 2 · 왼쪽 2칸 3개와 맞는 오른쪽 추 개수 찾기','Trial 2: balance left 2×3 by finding the right count');
leverFrames[1].startInputs={...leverFrames[1].inputs,rightCount:1};leverFrames[1].variable=['rightCount'];
